/** If this URL is a place, point the main map at its camera before MapLibre reads the hash. */
export function applyPlaceRoute() {
  let path = (location.pathname || '/').replace(/\/+$/, '') || '/';
  const base = '/earthmap';
  if (path === base || path.startsWith(base + '/')) path = path.slice(base.length) || '/';
  const place = PLACES[path];
  if (!place) return;
  const z = Math.min(7.5, Number(place.z));
  const hash = `#${z}/${place.lat}/${place.lng}`;
  if (!location.hash) {
    history.replaceState(null, '', location.pathname + location.search + hash);
  }
  if (place.title) document.title = place.title;
  const meta = document.querySelector('meta[name="description"]');
  if (meta && place.description) meta.setAttribute('content', place.description);
  const locale = path.match(/^\/(pt-BR|zh-Hans|ja|ko|de|fr|es|id|ru)(?=\/|$)/);
  if (locale) document.documentElement.lang = locale[1];
}

